tic;if TrackWorms    numfr = diff(FragmentFrames(Fragment,:));    bgframeinterval = round(min(50,numfr/10));     background = getbackgroundLowRes2(MovieName,2,1,FragmentFrames(Fragment,1),FragmentFrames(Fragment,2),bgframeinterval);    disp([datestr(now),' Background Processed for Movie ',num2str(MovieNum),', fragment ',num2str(Fragment)]);endfprintf('\n\n');clear('Tracks','AllData');Tracks = [];AllData = [];% % DyeData.Time = []; % % DyeData.Background = [];% % for a = 1:NumArenas% %     DyeData.Arena(NumArenas).Up = []; DyeData.Arena(NumArenas).Down = [];% % endLevel = 0;MOVsp = [];Settings = [];MovieObj = VideoReader(MovieName);for Frame = FragmentFrames(Fragment,1):FragmentFrames(Fragment,2)    % Get Frame    Mov = read(MovieObj, Frame);    %subtract the background from the frame    %the image becomes inverted with this operation    %Movsubtract = imsubtract(background, Mov.cdata(:,:,3));    Movdiv = 1 - min(double(Mov(:,:,1)+1)./(double(background)+1),1);    %Movdiv(TimerY,TimerX) = 0;  % clear timer region    Movdiv = Movdiv .* ~Mask;    % calculate threshold and animal size    if Level == 0        [Level,AnimalPix] = AutoThreshold(Movdiv);         Settings = [Settings; Frame, Level, AnimalPix];        disp(['Auto-calculating threshold: ',num2str(Level),' (Animal = ',num2str(AnimalPix),' pixels; ', ...               num2str(AnimalPix / PixelSize^2),' mm^2)']);        OLevel = Level;    else        %Level = OLevel;    end    %-----------    if TrackWorms    F2 = VideoFilter(Movdiv);    BW = im2bw(F2,Level);    [L,NUM] = bwlabel(BW);    if NUM > 300         % Reset autothreshold if too many objects        [Level,AnimalPix] = AutoThreshold(Movdiv);        Settings = [Settings; Frame, Level, AnimalPix]; disp(['(',num2str(Level),')']);%                 disp(['Auto-calculating threshold: ',num2str(Level),' (Animal = ',num2str(AnimalPix),' pixels; ', ...%                        num2str(AnimalPix / PixelSize^2 * 1e6),' um^2)']);        BW = im2bw(F2,Level);        [L,NUM] = bwlabel(BW);    end    if SaveThresholdMovie        BWsp = sparse(BW);        [i,j] = find(BWsp);        MOVsp = [MOVsp; uint16([i, j, repmat(Frame,size(i))])];    end    STATS = regionprops(L, {'Area', 'Centroid', 'Eccentricity', 'MajorAxisLength', ...        'MinorAxisLength', 'Orientation', 'Image', 'BoundingBox'});%     STATS = regionprops(L, {'Area', 'Centroid', 'FilledArea', 'Eccentricity', 'MajorAxisLength', ...%         'MinorAxisLength', 'Orientation', 'Image', 'BoundingBox'});    %         for i=1:length(STATS) STATS(i).Frame = Frame; end    % Identify all worms by size, get their centroid coordinates    WormIndices = find([STATS.Area] > MinWormArea*AnimalPix & [STATS.Area] < MaxWormArea*AnimalPix);    NumWorms = length(WormIndices);    if isempty(NumWorms)        break    end    WormCentroids = [STATS(WormIndices).Centroid];    WormCoordinates = [WormCentroids(1:2:2*NumWorms)', WormCentroids(2:2:2*NumWorms)'];    WormSizes = [STATS(WormIndices).Area];    %WormFilledAreas = [STATS(WormIndices).FilledArea];    WormEccentricities = [STATS(WormIndices).Eccentricity];    WormMajorAxes = [STATS(WormIndices).MajorAxisLength];    WormMinorAxes = [STATS(WormIndices).MinorAxisLength];    WormOrientation = [STATS(WormIndices).Orientation];    WormBox = [STATS(WormIndices).BoundingBox];    WormBoundingBox = [WormBox(1:4:4*NumWorms)', WormBox(2:4:4*NumWorms)'];    WormImage = [];    for wi = 1:length(WormIndices)        WormImage(wi).Image = STATS(WormIndices(wi)).Image;    end    for i=1:length(STATS)         AllData = [AllData; Frame, STATS(i).Area, STATS(i).Centroid, STATS(i).Eccentricity];    end    % Track worms    % -----------    if ~isempty(Tracks)        ActiveTracks = find([Tracks.Active]);    else        ActiveTracks = [];    end    % Update active tracks with new coordinates    for i = 1:length(ActiveTracks)        DistanceX = WormCoordinates(:,1) - Tracks(ActiveTracks(i)).LastCoordinates(1);        DistanceY = WormCoordinates(:,2) - Tracks(ActiveTracks(i)).LastCoordinates(2);        Distance = sqrt(DistanceX.^2 + DistanceY.^2);        [MinVal, MinIndex] = min(Distance);        if (MinVal <= MinDistance) & (abs(WormSizes(MinIndex) - Tracks(ActiveTracks(i)).LastSize) < SizeChangeThreshold)            Tracks(ActiveTracks(i)).Path = [Tracks(ActiveTracks(i)).Path; WormCoordinates(MinIndex, :)];            Tracks(ActiveTracks(i)).LastCoordinates = WormCoordinates(MinIndex, :);            Tracks(ActiveTracks(i)).Frames = [Tracks(ActiveTracks(i)).Frames, Frame];            Tracks(ActiveTracks(i)).Size = [Tracks(ActiveTracks(i)).Size, WormSizes(MinIndex)];            Tracks(ActiveTracks(i)).LastSize = WormSizes(MinIndex);            %Tracks(ActiveTracks(i)).FilledArea = [Tracks(ActiveTracks(i)).FilledArea, WormFilledAreas(MinIndex)];            Tracks(ActiveTracks(i)).Eccentricity = [Tracks(ActiveTracks(i)).Eccentricity, WormEccentricities(MinIndex)];            Tracks(ActiveTracks(i)).MajorAxes = [Tracks(ActiveTracks(i)).MajorAxes, WormMajorAxes(MinIndex)];            Tracks(ActiveTracks(i)).MinorAxes = [Tracks(ActiveTracks(i)).MinorAxes, WormMinorAxes(MinIndex)];            Tracks(ActiveTracks(i)).Orientation = [Tracks(ActiveTracks(i)).Orientation, WormOrientation(MinIndex)];            Tracks(ActiveTracks(i)).Box = [Tracks(ActiveTracks(i)).Box; WormBoundingBox(MinIndex,:)];            TrackFrameNum = length(Tracks(ActiveTracks(i)).Size);            Tracks(ActiveTracks(i)).Frame(TrackFrameNum).Image = WormImage(MinIndex).Image;            %Tracks(ActiveTracks(i)).FrameSize(TrackFrameNum) = sum(sum(Tracks(ActiveTracks(i)).Frame(TrackFrameNum).Image));            WormCoordinates(MinIndex,:) = NaN;            %WormSizes(MinIndex) = [];            %WormFilledAreas(MinIndex) = [];            %WormEccentricities(MinIndex) = [];            %WormMajorAxes(MinIndex) = [];            %WormMinorAxes(MinIndex) = [];            %WormOrientation(MinIndex) = [];            %WormBoundingBox(MinIndex,:) = [];            %WormImage = WormImage([1:MinIndex-1,MinIndex+1:end]).Image;        else            Tracks(ActiveTracks(i)).Active = 0;            if length(Tracks(ActiveTracks(i)).Frames) < MinTrackLength                Tracks(ActiveTracks(i)) = [];                ActiveTracks = ActiveTracks - 1;            end        end    end    % Start new tracks for coordinates not assigned to existing tracks    NumTracks = length(Tracks);    for i = 1:length(WormCoordinates(:,1))        Index = NumTracks + i;        Tracks(Index).Active = 1;        Tracks(Index).Path = WormCoordinates(i,:);        Tracks(Index).LastCoordinates = WormCoordinates(i,:);        Tracks(Index).Frames = Frame;        Tracks(Index).Size = WormSizes(i);        Tracks(Index).LastSize = WormSizes(i);        %Tracks(Index).FilledArea = WormFilledAreas(i);        Tracks(Index).Eccentricity = WormEccentricities(i);        Tracks(Index).MajorAxes = WormMajorAxes(i);        Tracks(Index).MinorAxes = WormMinorAxes(i);        Tracks(Index).Orientation = WormOrientation(i);        Tracks(Index).Box = WormBoundingBox(i,:);        Tracks(Index).Frame(1).Image = WormImage(i).Image;    end    % Display every PlotFrameRate'th frame    if ~mod(Frame, PlotFrameRate)        t1 = toc;        figure(1);        PlotFrame(WTFigH, Mov, Tracks);        %anperobj = [0, round([STATS.Area]/AnimalPix)+1];        FigureName = ['Movie ',num2str(MovieNum),': ',ShortMovieName, ...            ' - Frame ', num2str(Frame)];        set(WTFigH, 'Name', FigureName);        [Level,AnimalPix] = AutoThreshold(Movdiv);        Settings = [Settings; Frame, Level, AnimalPix];        t2 = toc; tic;        fps = PlotFrameRate/t1;        fprintf('\nFrame: %d - Time: %f fps (%f s) Level: (%f/%d)',Frame,fps,t2-t1,Level,AnimalPix)                 PercentComplete = round(100*(Frame - FragmentFrames(Fragment,1)) / diff(FragmentFrames(Fragment,:)));        ProgFileName = fullfile(TempFolder,['_F',int2str(Fragment)]);        delete([ProgFileName,'*']);        save([ProgFileName,'.',int2str(PercentComplete)],'PercentComplete');                 %fprintf('\n');%         if (t1/PlotFrameRate) > 10     % stop if it takes too long to analyze- probably an error            break;        end    end%     %try to free up memory?%     if PackMemory%         if ~mod(Frame,PackMemory);%             cwd = pwd;%             cd(tempdir);%             pack%             cd(cwd)%             fprintf('<MEM Pack>');%         end%     end%             if rem(Frame - FragmentFrames(1,1),120) == 0 & (Frame - FragmentFrames(1,1) < 600)%                 figure(2);%clf;%                 hist(AllData(:,2),100);%                 title(['Worm Area: Min = ',num2str(MinWormArea),'; Max = ',num2str(MaxWormArea)]);%             end    end    %--------% %     if TrackDye% %         Movdata = Mov(:,:,3);% %         bgimage = imcrop(Movdata,File(MovieNum).BgBox);% %         bgavg = mean(reshape(bgimage,[],1));% % % %         for a = 1:NumArenas% %             upimage = imcrop(Movdata,File(MovieNum).Arena(a).UpBox);% %             downimage = imcrop(Movdata,File(MovieNum).Arena(a).DnBox);% % % % %                 if Gradient% % %                     % record the intensity along the Y-direction, taking only% % %                     % the brightest 1/2 in the x-direction% % %                     uplist = sort(upimage,2,'descend');% % %                     upavg = mean(uplist(:,1:round(size(uplist,2)/2)),2);% % % % % %                     downlist = sort(downimage,2,'descend');% % %                     downavg = mean(downlist(:,1:round(size(downlist,2)/2)),2);% % % % % %                     DyeData.Up = [DyeData.Up, upavg];% % %                     DyeData.Down = [DyeData.Down, downavg];% % %                 else% %             uplist = sort(reshape(upimage,[],1),'descend');% %             upavg = mean(uplist(1:round(length(uplist)/2))); %just average the brightest 1/2 of pixels (in case a worm is in field)% % % %             downlist = sort(reshape(downimage,[],1),'descend');% %             downavg = mean(downlist(1:round(length(downlist)/2)));% % % %             DyeData.Arena(a).Up = [DyeData.Arena(a).Up, upavg-bgavg];% %             DyeData.Arena(a).Down = [DyeData.Arena(a).Down, downavg-bgavg];% % %                 end% %         end% % % % % %         DyeData.Time = [DyeData.Time, Frame/FrameRate];% % % %         DyeData.Background = [DyeData.Background, bgavg];% %     end    if mod(Frame,6) == 0 fprintf('-'); end    if mod(Frame,6) == 1 fprintf('\b\\'); end    if mod(Frame,6) == 2 fprintf('\b|'); end    if mod(Frame,6) == 3 fprintf('\b/'); end    if mod(Frame,6) == 4 fprintf('\b='); end    if mod(Frame,6) == 5 fprintf('\b+'); endend    % END for Frame = 1:FileInfo.NumFrames% Get rid of invalid tracksDeleteTracks = [];for i = 1:length(Tracks)    if length(Tracks(i).Frames) < MinTrackLength        DeleteTracks = [DeleteTracks, i];    endendTracks(DeleteTracks) = [];% Save Tracks% % for a = 1:NumArenas% %     DyeData.Arena(a).UpBox = File(MovieNum).Arena(a).UpBox;% %     DyeData.Arena(a).DnBox = File(MovieNum).Arena(a).DnBox;% %     DyeData.Arena(a).TrackBox = File(MovieNum).Arena(a).TrackBox;% % end% % DyeData.BgBox = File(MovieNum).BgBox;ExpData.PixelSize = File(MovieNum).PixelSize;ExpData.ArenaSize = File(MovieNum).ArenaSize;ExpData.FrameRate = FrameRate;ExpData.MovieNum = MovieNum;ExpData.TrackTime = datestr(now);ExpData.TrackedFrames = FrameNum;ExpData.TrackStats.MinWormArea = MinWormArea;  ExpData.TrackStats.MaxWormArea = MaxWormArea;ExpData.TrackStats.AnimalPix = AnimalPix;  ExpData.TrackStats.Level = Level;ExpData.TrackStats.MinDistance = MinDistance;ExpData.TrackStats.SizeChangeThreshold = SizeChangeThreshold;ExpData.TrackStats.MinTrackLength = MinTrackLength;ExpData.TrackSettings = Settings;% Update status fileloadsuccess = 0;while ~loadsuccess     try        load(StatusFile,'File');        loadsuccess = 1;    catch        disp('Error loading status file.  Retrying...');        pause(5);    endend                File(MovieNum).CompletedFragments(Fragment) = 1;File(MovieNum).CompTime = now;save(StatusFile,'File');disp('*** Status file updated ***');% Save Fragment Filesavesuccess = 0;while ~savesuccess    try        disp([datestr(now),' Saving Data for Movie ',num2str(MovieNum),', fragment ',num2str(Fragment)]);        if SaveAll% %             save(char(FragmentSaveNames(Fragment)), 'Tracks', 'AllData', 'DyeData', 'background', 'ExpData', 'File');            save(char(FragmentSaveNames(Fragment)), 'Tracks', 'AllData', 'background', 'ExpData', 'File');        else% %             save(char(FragmentSaveNames(Fragment)), 'Tracks', 'DyeData', 'background', 'ExpData', 'File');            save(char(FragmentSaveNames(Fragment)), 'Tracks', 'background', 'ExpData', 'File');        end         if SaveThresholdMovie            save([MovieName,'_',num2str(Fragment),'.mat'],'MOVsp','Settings');        end        disp([datestr(now),' *** Save complete *** ']);        savesuccess = 1;    catch        disp(' Error while saving... retrying');        lasterr        pause(10);    endend%Plot Summaryif 0    figure(2);    subplot(2,File(MovieNum).Fragments,Fragment);    barh(0:5:500,-(log10(histL+1))); hold on;    barh(0:5:500,(log10(histR+1)));     axis ij tight    set(gca,'YLim',[0 500]);    xsc = get(gca,'XLim'); plot(xsc,MinWormArea*[1 1],'b'); plot(xsc,MaxWormArea*[1 1],'b');    subplot(2,File(MovieNum).Fragments,File(MovieNum).Fragments+Fragment);    barh(0:10:850,-posL); hold on;    barh(0:10:850,posR);    axis ij tight    set(gca,'YLim',[0 850]);         endif Q    pause(30);    quitend